package wlgen

import (
	"fmt"
	"go/format"
	"strings"
)

// Options say how the generated file refers to its C side.
type Options struct {
	// Header is the wayland-scanner client header to include; empty for the
	// core protocol, whose header is <wayland-client.h>.
	Header string
	// Source names the XML file in the generated-code marker.
	Source string
}

// display is the core interface the wlproto runtime owns itself:
// libwayland handles its events, and the runtime sends its two requests.
const display = "wl_display"

// reserved are the exported methods of wlproto.Proxy a request must not
// shadow.
var reserved = map[string]bool{"ID": true, "Version": true, "Ptr": true, "Valid": true}

// Generate writes the Go wrappers of p for package wlproto.
func Generate(p *Protocol, o Options) ([]byte, error) {
	g := &gen{}
	source := o.Source
	if source == "" {
		source = p.Name + ".xml"
	}
	g.line("// Code generated by wlgen from %s; DO NOT EDIT.", source)
	g.line("")
	g.line("package wlproto")
	g.line("")
	g.line("/*")
	if o.Header == "" {
		g.line("#include <wayland-client.h>")
	} else {
		g.line("#include %q", o.Header)
	}
	g.line("*/")
	g.line(`import "C"`)
	for _, iface := range p.Interfaces {
		if iface.Name == display {
			continue
		}
		if err := g.iface(iface); err != nil {
			return nil, err
		}
	}
	src, err := format.Source([]byte(g.b.String()))
	if err != nil {
		return nil, fmt.Errorf("generated source for %s: %w", p.Name, err)
	}
	return src, nil
}

type gen struct{ b strings.Builder }

func (g *gen) line(format string, args ...any) {
	fmt.Fprintf(&g.b, format, args...)
	g.b.WriteByte('\n')
}

func (g *gen) iface(i Interface) error {
	typ := camel(i.Name)
	g.line("")
	summary := strings.Join(strings.Fields(i.Summary), " ")
	if summary == "" {
		g.line("// %sInterface is %s, version %d.", typ, i.Name, i.Version)
	} else {
		g.line("// %sInterface is %s, version %d: %s.", typ, i.Name, i.Version, summary)
	}
	g.line("var %sInterface = &Interface{Name: %q, Version: %d, c: &C.%s_interface, "+
		"new: func() Object { return new(%s) }}", typ, i.Name, i.Version, i.Name, typ)
	g.line("")
	g.line("// %s is a %s proxy. Its On fields handle the events; set them", typ, i.Name)
	g.line("// before the events can arrive.")
	g.line("type %s struct {", typ)
	g.line("Proxy")
	for _, e := range i.Events {
		g.line("// On%s handles %s.%s.", camel(e.Name), i.Name, e.Name)
		g.line("On%s func(%s)", camel(e.Name), params(e.Args, true))
	}
	g.line("}")
	g.enums(typ, i)
	hasDestroy := false
	for opcode, r := range i.Requests {
		name := camel(r.Name)
		if reserved[name] {
			return fmt.Errorf("%s.%s: the method would shadow Proxy.%s", i.Name, r.Name, name)
		}
		hasDestroy = hasDestroy || name == "Destroy"
		g.request(i, typ, opcode, r)
	}
	if !hasDestroy {
		g.line("")
		g.line("// Destroy forgets the proxy without telling the compositor (%s has", i.Name)
		g.line("// no destroy request).")
		g.line("func (o *%s) Destroy() { o.forget() }", typ)
	}
	g.dispatch(i, typ)
	return nil
}

func (g *gen) enums(typ string, i Interface) {
	for _, e := range i.Enums {
		g.line("")
		g.line("// Values of %s.%s.", i.Name, e.Name)
		g.line("const (")
		for _, entry := range e.Entries {
			g.line("%s%s%s = %s", typ, camel(e.Name), camel(entry.Name), entry.Value)
		}
		g.line(")")
	}
}

// goType is an argument's Go type: in events (handler parameters) and in
// requests (method parameters) alike.
func goType(a Arg) string {
	switch a.Type {
	case "int":
		return "int32"
	case "uint":
		return "uint32"
	case "fixed":
		return "Fixed"
	case "string":
		return "string"
	case "fd":
		return "int"
	case "array":
		return "[]byte"
	case "object", "new_id":
		if a.Interface == "" {
			return "Object"
		}
		return "*" + camel(a.Interface)
	}
	return "any"
}

// params is a parameter list. In requests the new_id is the result, not a
// parameter, except an untyped one, which becomes interface and version.
func params(args []Arg, event bool) string {
	var ps []string
	for _, a := range args {
		switch {
		case a.Type == "new_id" && !event && a.Interface == "":
			ps = append(ps, "iface *Interface", "version uint32")
		case a.Type == "new_id" && !event:
		default:
			ps = append(ps, lowerCamel(a.Name)+" "+goType(a))
		}
	}
	return strings.Join(ps, ", ")
}

func (g *gen) request(i Interface, typ string, opcode int, r Message) {
	name := camel(r.Name)
	var created *Arg
	n := 0
	for k, a := range r.Args {
		if a.Type == "new_id" {
			created = &r.Args[k]
			if a.Interface == "" {
				n += 2 // the interface name and version precede the id
			}
		}
		n++
	}
	result := ""
	if created != nil {
		result = " " + goType(*created)
	}
	g.line("")
	doc := fmt.Sprintf("// %s sends %s.%s", name, i.Name, r.Name)
	if r.Destructor() {
		doc += " and forgets the proxy"
	}
	if r.Since > 1 {
		doc += fmt.Sprintf(" (since version %d)", r.Since)
	}
	g.line("%s.", doc)
	g.line("func (o *%s) %s(%s)%s {", typ, name, params(r.Args, false), result)
	args := "nil"
	if n > 0 {
		args = "a[:]"
		g.line("var a [%d]argument", n)
	}
	slot := 0
	for _, a := range r.Args {
		v := lowerCamel(a.Name)
		switch a.Type {
		case "int":
			g.line("a[%d].setInt(%s)", slot, v)
		case "uint":
			g.line("a[%d].setUint(%s)", slot, v)
		case "fixed":
			g.line("a[%d].setFixed(%s)", slot, v)
		case "fd":
			g.line("a[%d].setFd(%s)", slot, v)
		case "string":
			g.line("%sC := cString(%s)", v, v)
			g.line("defer freeC(%sC)", v)
			g.line("a[%d].setPtr(%sC)", slot, v)
		case "object":
			g.line("if %s != nil {", v)
			g.line("a[%d].setProxy(%s.proxy())", slot, v)
			g.line("}")
		case "new_id":
			if a.Interface == "" {
				g.line("ifaceC := cString(iface.Name)")
				g.line("defer freeC(ifaceC)")
				g.line("a[%d].setPtr(ifaceC)", slot)
				g.line("a[%d].setUint(version)", slot+1)
				slot += 2
			}
		}
		slot++
	}
	switch {
	case created != nil && created.Interface == "":
		g.line("return o.create(%d, %s, iface, version)", opcode, args)
	case created != nil:
		g.line("created, _ := o.create(%d, %s, %sInterface, 0).(%s)", opcode, args,
			camel(created.Interface), goType(*created))
		g.line("return created")
	case r.Destructor():
		g.line("o.destructor(%d, %s)", opcode, args)
	default:
		g.line("o.request(%d, %s)", opcode, args)
	}
	g.line("}")
}

// OptionsFor are the options for the protocol file at path (slash
// separated, as in a go:generate line): wayland.xml is the core protocol,
// any other NAME.xml includes wayland-scanner's NAME-client-protocol.h.
func OptionsFor(path string) Options {
	base := path[strings.LastIndex(path, "/")+1:]
	name := strings.TrimSuffix(base, ".xml")
	if name == "wayland" {
		return Options{Source: path}
	}
	return Options{Header: name + "-client-protocol.h", Source: path}
}
